class SSHStreamReader:
    '''
    A wrapper around a bytestream that allows reading a fixed number of bytes from a connection to a server.
    '''

    def __init__(self, stream):
        '''
        @param stream:  The stream to read from.
        '''
        self._stream = stream

    def read_bytes(self, num_bytes: int) -> bytes:
        '''
        Reads a fixed number of bytes from the stream.
        @param num_bytes:  The number of bytes to read.
        @return:    The read bytes.
        @raise ValueError: If num_bytes is not a positive integer.
        @raise EOFError: If not enough bytes are available in the stream.
        '''
        if not isinstance(num_bytes, int) or num_bytes <= 0:
            raise ValueError("num_bytes must be a positive integer")

        max_read_size = 4096  # Define a maximum read size for safety
        if num_bytes > max_read_size:
            raise ValueError(f"num_bytes must not exceed {max_read_size}")

        total_bytes = bytearray()
        while len(total_bytes) < num_bytes:
            try:
                chunk = self._stream.read(num_bytes - len(total_bytes))
                if not chunk:
                    break  # No more data available, exit loop
                total_bytes.extend(chunk)
            except Exception as e:
                raise IOError(f"An error occurred while reading the stream: {e}")

        if len(total_bytes) < num_bytes:
            raise EOFError("Not enough bytes available from stream; expected more")

        return bytes(total_bytes)

