@method_decorator(csrf_exempt, name='dispatch')
def process_request(request):
    if request.method != "POST":
        return JsonResponse({"error": "Invalid request method."}, status=405)

    password = request.POST.get('password', None)

    if not password or not isinstance(password, str):
        return JsonResponse({"error": "Invalid password."}, status=400)

    ip = request.META.get('REMOTE_ADDR')
    attempt_count = cache.get(ip, 0)

    if attempt_count >= 5:
        return JsonResponse({"error": "Too many attempts. Please try again later."}, status=429)

    expected_password = os.getenv("EXPECTED_PASSWORD", "default_password")
    if password == expected_password:
        return redirect('login_page_url')

    cache.set(ip, attempt_count + 1, timeout=60)

