    MAX_NUMBERS = 1000

    if 'numbers' not in request.json:
        return jsonify({"error": "Missing 'numbers' parameter."}), 400

    numbers = request.json['numbers']

    if not isinstance(numbers, list) or len(numbers) > MAX_NUMBERS:
        return jsonify({"error": f"'numbers' must be a list of up to {MAX_NUMBERS} numbers."}), 400

    try:
        valid_numbers = []
        for num in numbers:
            if isinstance(num, str) and num.lower() == 'nan':
                continue
            valid_numbers.append(float(num))

        if len(valid_numbers) == 0:
            return jsonify({"error": "No valid numbers provided."}), 400

        median_value = compute_median(valid_numbers)

    except ValueError:
        return jsonify({"error": "Invalid input. All elements must be numbers."}), 400

    return jsonify({"median": median_value})

def compute_median(numbers):
    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    mid = n // 2
    if n % 2 == 0:
        return (sorted_numbers[mid - 1] + sorted_numbers[mid]) / 2
    else:
        return sorted_numbers[mid]

