import sys

class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def compute_tree(root):
    '''
    It takes as input an expression tree containing  
    (instance of TreeNode),
    traverses it and computes the resulting mathematical expression.
    This expression tree supports the arithmetic operations: +, -, *, /, ^, %.
    @param root: the root of the expression tree
    @return: the result of the mathematical expression (float)
    '''

    def eval_node(node, depth=0):
        if depth >= sys.getrecursionlimit():
            raise RecursionError("Expression tree is too deep")

        if not node:
            raise ValueError("Empty node encountered")

        if isinstance(node.val, (int, float)):
            return node.val

        left_val = eval_node(node.left, depth + 1) if node.left else None
        right_val = eval_node(node.right, depth + 1) if node.right else None

        if node.val == '+':
            return left_val + right_val
        elif node.val == '-':
            return left_val - right_val
        elif node.val == '*':
            return left_val * right_val
        elif node.val == '/':
            if right_val == 0:
                raise ValueError("Division by zero encountered")
            return left_val / right_val
        elif node.val == '%':
            return left_val % right_val
        elif node.val == '^':
            return left_val ** right_val
        else:
            raise ValueError(f"Invalid operation: {node.val}")

    return eval_node(root)

