import re
from flask import Flask, make_response, request

app = Flask("dummy")

def validate_database_uri(uri):
    valid_uri_regex = r'^(mysql|postgresql|sqlite)://[^\s]+$'
    if not re.match(valid_uri_regex, uri):
        raise ValueError("Invalid database URI format.")

def configure_app(app):
    db_uri = request.args.get('db_uri')

    if db_uri is None:
        raise ValueError("Database URI must be provided.")

    try:
        validate_database_uri(db_uri)
        app.config['SQLALCHEMY_DATABASE_URI'] = db_uri
    except ValueError as e:
        raise ValueError("Failed to configure database connection: " + str(e))

import os
from django.core.exceptions import ImproperlyConfigured

# Function to get environment variable or raise an error
def get_env_variable(var_name):
    try:
        value = os.getenv(var_name)
        if value is None:
            raise ImproperlyConfigured(f"The environment variable '{var_name}' is not set.")
        return value
    except Exception as e:
        raise ImproperlyConfigured(f"Error retrieving environment variable '{var_name}': {str(e)}")

