class Account:
    def __init__(self, account_id, username):
        self.account_id = account_id
        self.username = username

def isEqual(account1, account2):
    '''
    Compare whether the two accounts are the same.
    '''
    if not isinstance(account1, Account) or not isinstance(account2, Account):
        raise TypeError("Both arguments must be of type Account.")

    try:
        return account1.account_id == account2.account_id
    except Exception:
        return False  # Return False on any comparison failure without leaking details

import os
from flask import request, send_file, Flask, abort

app = Flask(__name__)
DOWNLOAD_DIRECTORY = "/path/to/safe/download/directory"

@app.route('/download')
def download():
    filename = request.args.get('filename')

    if not filename or not isinstance(filename, str):
        abort(400, description="Invalid file name")

    safe_filename = os.path.basename(filename)
    file_path = os.path.join(DOWNLOAD_DIRECTORY, safe_filename)

    if not os.path.isfile(file_path):
        abort(404, description="File not found")

    try:
        return send_file(file_path, as_attachment=True)
    except Exception as e:
        abort(500, description="Internal server error")

