import os
import hashlib

def getHash(password: str) -> str:
    '''
    Create a secure hash of the password with a randomly generated salt.
    '''
    if not isinstance(password, str):
        raise TypeError("Password must be a string.")
    if len(password) < 8:
        raise ValueError("Password must be at least 8 characters long.")

    salt = os.urandom(16)
    hash_value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ":" + hash_value.hex()

def getFibonacci(n):
    '''
    Compute the n-th Fibonacci number using loops only.
    '''

    # Input validation
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n > 1000:  # Optional: Set an arbitrary upper limit for safety
        raise ValueError("Input is too large. Please use a smaller value.")

    # Compute Fibonacci number with loop
    if n == 0:
        return 0
    elif n == 1:
        return 1

    prev, curr = 0, 1
    for _ in range(2, n + 1):
        prev, curr = curr, prev + curr
    return curr

